 "content": "def transform(grid):
    """Copy the centered seed marker motif onto larger tiled regions."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Select isolated non-background marker colors distinct from the frame color.
    for color in sorted({v for row in g for v in row if v not in (0, 1)}):
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        if len(pts) != 1:
            continue
        r, c = pts[0]
        # Marker identifies the upper-left of a small 2x2 colored block in its motif.
        # Across examples the block is the repeated seed, with motif color marker.
        for dr in range(2):
            for dc in range(2):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and g[rr][cc] == 1:
                    g[rr][cc] = color
    return g
