{
 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Marked seed blocks are 2x2 and use the marker color. Replicate the seed
    # into the remaining 2x2 unit cells of each marked patterned panel.
    for color in sorted({v for row in g for v in row if v not in (0, 1)}):
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        if len(pts) != 1:
            continue
        r, c = pts[0]
        # Work only in the contiguous 1-valued patterned field around seed.
        for dr in range(-8, 9, 2):
            for dc in range(-8, 9, 2):
                rr, cc = r + dr, c + dc
                if rr < 0 or cc < 0 or rr + 1 >= h or cc + 1 >= w:
                    continue
                if all(g[rr + y][cc + x] == 1 for y in range(2) for x in range(2)):
                    # Restrict to cells connected by nearby 1-pattern around the seed.
                    if abs(dr) <= 8 and abs(dc) <= 8:
                        for y in range(2):
                            for x in range(2):
                                g[rr + y][cc + x] = color
    return g
