 "content": "def transform(grid):
    # Copy 2x2 motif patches described by each isolated marker color. The demo
    # pairs show the marker's nearest patterned unit is repeated at that same
    # relative location in the other motif panels.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    markers = [(r, c, out[r][c]) for r in range(h) for c in range(w)
               if out[r][c] not in (0, 1)]
    for r, c, color in markers:
        # The marker belongs to one of the small repeated panels. Apply it to
        # every available 2x2 foreground patch in that contiguous local region.
        for rr in range(max(0, r - 8), min(h - 1, r + 9)):
            for cc in range(max(0, c - 8), min(w - 1, c + 9)):
                if all(out[rr + dr][cc + dc] == 1 for dr in range(2) for dc in range(2)):
                    # Demand a 4x4 tile context to avoid painting single strands.
                    if sum(out[rr + y][cc + x] == 1
                           for y in range(max(0, -rr), min(4, h - rr))
                           for x in range(max(0, -cc), min(4, w - cc))) >= 8:
                        for dr in range(2):
                            for dc in range(2):
                                out[rr + dr][cc + dc] = color
    return out
